import{c as t,Q as a,j as r,m as n}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Graph Engineering with Dynamic Workflows: run 1,000 agents in 7 steps (FULL GUIDE)","description":"","frontmatter":{"url":"https://x.com/0xClodex/status/2079541141188272354","title":"Graph Engineering with Dynamic Workflows: run 1,000 agents in 7 steps (FULL GUIDE)","author":"Clodex","archived":"2026-07-26T00:00:00.000Z","handle":"@0xClodex","published":"2026-07-21T00:00:00.000Z","stats":"32 likes · 1 retweets · 68 bookmarks · 52316 views","tags":["graph-engineering","dynamic-workflows","bun-rewrite","worktree-isolation","cost-tiering"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-21-@0xClodex-272354.md","filePath":"research/tweets/2026-07-21-@0xClodex-272354.md","lastUpdated":1785909234000}'),o={name:"research/tweets/2026-07-21-@0xClodex-272354.md"};function i(s,e,h,l,d,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="graph-engineering-with-dynamic-workflows-run-1-000-agents-in-7-steps-full-guide-—-0xclodex" tabindex="-1">Graph Engineering with Dynamic Workflows: run 1,000 agents in 7 steps (FULL GUIDE) — @0xClodex <a class="header-anchor" href="#graph-engineering-with-dynamic-workflows-run-1-000-agents-in-7-steps-full-guide-—-0xclodex" aria-label="Permalink to &quot;Graph Engineering with Dynamic Workflows: run 1,000 agents in 7 steps (FULL GUIDE) — @0xClodex&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/0xClodex/status/2079541141188272354" target="_blank" rel="noreferrer">https://x.com/0xClodex/status/2079541141188272354</a><strong>作者</strong>：Clodex（@0xClodex） <strong>發布日期</strong>：2026-07-21 <strong>收錄日期</strong>：2026-07-26 <strong>類型</strong>：Twitter Article <strong>統計</strong>：32 likes · 1 retweets · 68 bookmarks · 52316 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Dynamic workflows, subagents, and verification - the way one founder swapped a whole language out in 11 days. One founder pointed a fleet of Claude agents at a real production runtime and swapped the whole language out - 500k+ lines of Zig rewritten in Rust in 11 days. Bun&#39;s Jarred Sumner didn&#39;t hand-write it. He orchestrated it. The wild part isn&#39;t the size - it&#39;s that the plan lived in a script, not a context window: a graph of jobs that fanned out across hundreds of agents, checked each other, and folded into one answer. That&#39;s graph engineering, and Claude Code ships the tooling for it now. Here&#39;s the whole thing in 7 steps. (before the deep dive - I post fresh AI alpha, no hype. follow @0xClodex )</p><hr><h2 id="step-1-know-when-to-stop-prompting" tabindex="-1">Step 1 - Know when to stop prompting <a class="header-anchor" href="#step-1-know-when-to-stop-prompting" aria-label="Permalink to &quot;Step 1 - Know when to stop prompting&quot;">​</a></h2><p>[圖 1] Subagents already fan out and come back - Claude delegates to a fleet, they run once, it merges. So a single fan-out is not the reason to reach for a workflow. The reason is what happens after the fan-out. The moment one stage&#39;s result decides the next - route this, score that, filter, loop, retry, verify - you&#39;ve stopped prompting and started orchestrating.</p><hr><h2 id="step-2-move-the-plan-into-code" tabindex="-1">Step 2 - Move the plan into code <a class="header-anchor" href="#step-2-move-the-plan-into-code" aria-label="Permalink to &quot;Step 2 - Move the plan into code&quot;">​</a></h2><p>[圖 2] A dynamic workflow is a plain JavaScript script that Claude writes for the task you describe, and a runtime runs it in the background while your session stays free. The loop, the branching, the intermediate results - all of it lives in the script. That&#39;s the difference from just spawning more agents. With subagents, Claude is the orchestrator and every result lands in its context window. At a handful that&#39;s fine; at fifty the window fills and the model starts fighting to stay on task. A workflow keeps the intermediate mess out of the window entirely - so it scales to hundreds without drowning.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ultracode : audit every endpoint for missing auth</span></span></code></pre></div><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">deep</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">research </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">question</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>You start one by saying &quot;use a workflow…&quot; or dropping the keyword ultracode into your prompt. Requires Claude Code v2.1.154+, on all paid plans (on Pro, flip it on in /config).</p><hr><h2 id="step-3-give-every-agent-a-contract" tabindex="-1">Step 3 -Give every agent a contract <a class="header-anchor" href="#step-3-give-every-agent-a-contract" aria-label="Permalink to &quot;Step 3 -Give every agent a contract&quot;">​</a></h2><p>[圖 3] A node you can&#39;t reason about is a node you can&#39;t wire into a graph. The fix is a contract. When you hand an agent() call a JSON schema, the subagent is forced to return structured data in that exact shape - and if it doesn&#39;t match, the runtime retries instead of handing you a wall of text to clean up. This is the quiet difference between a node a graph can consume and a node that only works when a human reads its output.</p><hr><h2 id="step-4-fan-out-then-pick-pipeline-over-barrier" tabindex="-1">Step 4 - Fan out -then pick pipeline over barrier <a class="header-anchor" href="#step-4-fan-out-then-pick-pipeline-over-barrier" aria-label="Permalink to &quot;Step 4 - Fan out -then pick pipeline over barrier&quot;">​</a></h2><p>[圖 4] This is t makes everything wait for the slowest node before the next stage starts. A pipeline() streams each item through all stages independently - item A can be in stage 3 while item B is still in stage 1. &quot;It feels cleaner&quot; is not a reason to use a barrier. Barrier latency is real, measurable, wasted time. A barrier makes everything wait for the slowest node before the next stage starts. A pipeline() streams each item through all stages independently - item A can be in stage 3 while item B is still in stage 1. &quot;It feels cleaner&quot; is not a reason to use a barrier. Barrier latency is real, measurable, wasted time.</p><hr><h2 id="step-5-put-a-skeptic-on-every-finding" tabindex="-1">Step 5 - Put a skeptic on every finding <a class="header-anchor" href="#step-5-put-a-skeptic-on-every-finding" aria-label="Permalink to &quot;Step 5 - Put a skeptic on every finding&quot;">​</a></h2><p>[圖 5] The real leverage of a graph isn&#39;t more agents - it&#39;s the structure you can wrap around them to earn confidence. A verifier sits on the edge before a result is allowed downstream, and its only job is to try to kill the finding. If it survives, it passes. If not, it never reaches the answer. The bundled /deep-research workflow is exactly this pattern shipping in production: fan out across angles, cross-check the sources against each other, vote on every claim, and filter out the ones that didn&#39;t survive. As of a recent build, a claim the verifiers can&#39;t check gets listed as unverified rather than silently dropped.</p><hr><h2 id="step-6-isolate-the-writers" tabindex="-1">Step 6 - Isolate the writers <a class="header-anchor" href="#step-6-isolate-the-writers" aria-label="Permalink to &quot;Step 6 - Isolate the writers&quot;">​</a></h2><p>[圖 6] Reading in parallel is free. Writing in parallel is where things break. When many agents edit files at the same time, they collide. The fix is isolation: each agent gets its own copy of the tree - a git worktree - does its work there, and merges cleanly at the end. Sumner&#39;s Bun port leaned on exactly this: at peak, several workflows ran at once, each in its own worktree, so hundreds of file-ports never trampled each other.</p><hr><h2 id="step-7-converge-tier-the-models-save-the-run" tabindex="-1">Step 7 - Converge, tier the models, save the run <a class="header-anchor" href="#step-7-converge-tier-the-models-save-the-run" aria-label="Permalink to &quot;Step 7 - Converge, tier the models, save the run&quot;">​</a></h2><p>[圖 7] Some jobs are unknown-size - a bug sweep where fixing one reveals three more. That needs a loop, and a loop that doesn&#39;t converge is just a budget on fire. The pattern that converges: keep going until two rounds in a row surface nothing new, then stop. Not every node needs your best model. Run the boring, repetitive nodes on something cheaper and spend the expensive tokens where judgment actually lives. Check /model before a big run and route stages down where you can. And when a run does what you wanted, save it. It lands in .claude/workflows/, version-controlled, and becomes a /name command anyone who clones the repo can launch. The graph you drew once is now infrastructure.</p><hr><h2 id="the-whole-thing-on-a-real-codebase" tabindex="-1">The whole thing, on a real codebase <a class="header-anchor" href="#the-whole-thing-on-a-real-codebase" aria-label="Permalink to &quot;The whole thing, on a real codebase&quot;">​</a></h2><p>[圖 8] Every step above shows up here. One workflow mapped the correct Rust memory lifetime for every struct field. A second dispatched hundreds of parallel agents to write behavior-identical .rs files, with two adversarial reviewers assigned to each output. A fix loop drove the build and tests until they passed. And after the port landed, another workflow ran overnight hunting unnecessary data copies and opening PRs.</p><hr><h2 id="prompter-or-architect" tabindex="-1">Prompter or architect? <a class="header-anchor" href="#prompter-or-architect" aria-label="Permalink to &quot;Prompter or architect?&quot;">​</a></h2><p>The linear agent - step one, step two, step three, each waiting politely for the last - was never the ceiling. It was just the first shape, the one everyone reaches for because it matches how we type. Once you can see the nodes and the edges, you stop asking the agent to do more and start asking the graph to do it wider: fan out where the work is independent, put a skeptic on the edge where confidence matters, tier the models where judgment doesn&#39;t. Most people will keep queueing steps in a line. The ones who learn to draw the graph will run a fleet.</p><hr><h2 id="thanks-for-reading" tabindex="-1">Thanks for reading <a class="header-anchor" href="#thanks-for-reading" aria-label="Permalink to &quot;Thanks for reading&quot;">​</a></h2><p>I break down what&#39;s actually shipping in AI - the real mechanics, minus the hype. If this helped, come along. Follow @0xClodex</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：以 Jarred Sumner（Bun）「11 天把 500k+ 行 Zig 改寫成 Rust」的敘事包裝的 7 步驟 Graph Engineering 指南，內容與同批 @0xCodez 14 步驟文章高度重疊（node contract、pipeline 優於 barrier、verifier、worktree 隔離、model tiering、loop-until-dry），差異主要在敘事案例而非新機制。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>開場案例</strong>：文章以「Bun 的 Jarred Sumner 用 Claude agent 艦隊把 Zig 重寫成 Rust，11 天完成 500k+ 行」作為 graph engineering 的具象範例，強調「plan 活在 script 裡，不是 context window 裡」</li><li><strong>7 步驟骨架</strong>：何時該從 prompting 換成 orchestrating（Step 1）→ 把計畫寫進程式碼（Step 2）→ 每個 agent 給 schema contract（Step 3）→ fan-out 後選 pipeline 而非 barrier（Step 4）→ 每個 finding 配一個 skeptic verifier（Step 5）→ 平行寫入要用 git worktree 隔離（Step 6）→ 收斂條件 + model tiering + 存成可重跑的 workflow（Step 7）</li><li><strong>worktree 隔離的具體理由</strong>：讀取平行是免費的，寫入平行才會碰撞；文中稱 Bun 港口在尖峰時多個 workflow 同時跑、各自獨立 worktree，避免檔案互踩</li><li><strong>收斂規則</strong>與 @0xCodez 文章相同：連續兩輪無新發現才停止，避免無限迴圈燒預算</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>統計：32 likes・1 retweet・68 bookmarks・52,316 views（API 實測，本文互動數遠低於同批其他三則，樣本代表性有限）</li><li><strong>「500k+ 行 Zig 改寫成 Rust，11 天完成」——原文宣稱，未經查證</strong>：全文未附一手來源、commit 記錄或 Sumner 本人的原始貼文連結，無法獨立核實規模與工期</li><li>工具：Claude Code dynamic workflows，版本需求 v2.1.154+（與 @0xCodez 文章一致，兩篇疑似源自同一份官方素材或彼此參照）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li><strong>與 @0xCodez 同日前後發布、結構高度相似</strong>：兩篇文章共享「node/edge/contract」「pipeline &gt; barrier」「verifier」「worktree 隔離」「loop-until-dry」「model tiering」六個核心機制，且都引用 Bun 重寫案例佐證 verifier/worktree 段落——這種高度重合本身值得注意，可能是同一波「Graph Engineering」術語擴散下的模板化二次創作，而非各自獨立的一手觀察</li><li><strong>具體工期與規模數字（11 天、500k+ 行）沒有可查證來源</strong>，不應被當作可引用的效能證據；後續整合時只能作為敘事案例，不能作為量化佐證</li><li><strong>互動量遠低於同批其他三則</strong>（52K views vs 百萬級），與 @0xCodez 同主題文章相比缺乏獨立傳播力，可能是模板化內容的訊號之一</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>6/10</td><td>機制與 @0xCodez-330317 重複，可行動內容已被涵蓋，本篇無新增判準</td></tr><tr><td>B. 創新性 (20%)</td><td>3/10</td><td>與同批文章結構、案例高度重合，原創度低</td></tr><tr><td>C. 證據品質 (20%)</td><td>3/10</td><td>Bun 案例規模/工期無來源可查證；互動量低，市場驗證訊號弱</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>worktree 隔離與 model tiering 描述具體，但深度不及 @0xCodez 版本</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>7 步驟骨架仍可泛化到任何 orchestration 場景</td></tr><tr><td><strong>加權總分</strong></td><td><strong>4.75/10</strong></td><td>6×0.3+3×0.2+3×0.2+6×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip（僅作交叉參照） <strong>理由</strong>：核心機制已由 @0xCodez-330317 涵蓋且評分更高，本篇具體案例數字無法查證，僅保留作為「同波術語模板化擴散」的證據樣本，不單獨整合進 Rule。</p>',51)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
